"use client";

import { useEffect, useState, useCallback } from "react";
import Link from "next/link";
import { Loader2, BookOpen, TrendingUp, AlertTriangle, ChevronRight } from "lucide-react";

interface COInsight {
  coId: string;
  coCode: string;
  coDescription: string;
  totalQuestions: number;
  correctAnswers: number;
  masteryPct: number;
  level: string;
}

interface DifficultyBreakdown {
  difficulty: string;
  total: number;
  correct: number;
  pct: number;
}

interface Recommendation {
  coCode: string;
  coDescription: string;
  level: string;
  message: string;
}

interface CourseInfo {
  courseId: string;
  courseName: string;
  courseCode: string;
}

export default function StudentInsightsPage() {
  const [courses, setCourses] = useState<CourseInfo[]>([]);
  const [selectedCourse, setSelectedCourse] = useState<string>("");
  const [insights, setInsights] = useState<{
    coInsights: COInsight[];
    difficultyBreakdown: DifficultyBreakdown[];
    recommendations: Recommendation[];
    overallMastery: number;
  } | null>(null);
  const [loading, setLoading] = useState(true);
  const [insightsLoading, setInsightsLoading] = useState(false);

  useEffect(() => {
    (async () => {
      const res = await fetch("/api/student/my-courses");
      if (res.ok) {
        const data = await res.json();
        setCourses(data);
        if (data.length > 0) setSelectedCourse(data[0].courseId);
      }
      setLoading(false);
    })();
  }, []);

  const fetchInsights = useCallback(async (courseId: string) => {
    if (!courseId) return;
    setInsightsLoading(true);
    const res = await fetch(`/api/student/insights/${courseId}`);
    if (res.ok) setInsights(await res.json());
    setInsightsLoading(false);
  }, []);

  useEffect(() => {
    if (selectedCourse) fetchInsights(selectedCourse);
  }, [selectedCourse, fetchInsights]);

  const levelColor: Record<string, string> = {
    weak: "bg-red-500",
    developing: "bg-yellow-500",
    proficient: "bg-blue-500",
    mastered: "bg-emerald-500",
  };

  const levelBadgeColor: Record<string, string> = {
    weak: "bg-red-500/20 text-red-400",
    developing: "bg-yellow-500/20 text-yellow-400",
    proficient: "bg-blue-500/20 text-blue-400",
    mastered: "bg-emerald-500/20 text-emerald-400",
  };

  const diffColor: Record<string, string> = {
    easy: "text-emerald-400",
    medium: "text-yellow-400",
    hard: "text-red-400",
  };

  if (loading) {
    return (
      <div className="flex h-60 items-center justify-center">
        <Loader2 className="h-5 w-5 animate-spin text-white/20" />
      </div>
    );
  }

  return (
    <div>
      <div className="mb-8 flex items-center gap-3">
        <TrendingUp className="h-4 w-4 text-white/20" />
        <h2 className="text-xs font-bold uppercase tracking-[0.2em] text-white/20">Learning Insights</h2>
      </div>

      {/* Course Selector */}
      <div className="mb-8">
        <label className="mb-2 block text-[10px] font-bold uppercase tracking-widest text-white/30">Select Course</label>
        <select
          value={selectedCourse}
          onChange={(e) => setSelectedCourse(e.target.value)}
          className="w-full max-w-sm rounded border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-sm text-white outline-none focus:border-white/20"
        >
          {courses.map((c) => (
            <option key={c.courseId} value={c.courseId}>{c.courseName} ({c.courseCode})</option>
          ))}
        </select>
      </div>

      {insightsLoading ? (
        <div className="flex h-40 items-center justify-center">
          <Loader2 className="h-5 w-5 animate-spin text-white/20" />
        </div>
      ) : insights ? (
        <div className="space-y-8">
          {/* Overall Mastery */}
          <div className="rounded-xl border border-white/[0.04] bg-white/[0.01] p-6 text-center">
            <p className="text-[10px] font-bold uppercase tracking-widest text-white/30 mb-2">Overall Mastery</p>
            <p className={`text-5xl font-black ${insights.overallMastery >= 70 ? "text-emerald-400" : insights.overallMastery >= 40 ? "text-yellow-400" : "text-red-400"}`}>
              {insights.overallMastery}%
            </p>
          </div>

          {/* CO Mastery Bars */}
          <div>
            <h3 className="mb-4 text-[10px] font-bold uppercase tracking-widest text-white/20">Course Outcome Mastery</h3>
            {insights.coInsights.length === 0 ? (
              <div className="flex h-24 items-center justify-center rounded-xl border border-dashed border-white/[0.06]">
                <p className="text-xs font-bold text-white/20">No quiz data yet</p>
              </div>
            ) : (
              <div className="space-y-3">
                {insights.coInsights.map((co) => (
                  <div key={co.coId} className="rounded-lg border border-white/[0.04] bg-white/[0.01] p-4">
                    <div className="flex items-center justify-between mb-2">
                      <div className="flex items-center gap-2">
                        <span className="text-xs font-black text-white/50">{co.coCode}</span>
                        <span className="text-xs text-white/30 truncate max-w-xs">{co.coDescription}</span>
                      </div>
                      <div className="flex items-center gap-2">
                        <span className="text-xs font-black text-white/60">{co.masteryPct}%</span>
                        <span className={`rounded px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-widest ${levelBadgeColor[co.level]}`}>{co.level}</span>
                      </div>
                    </div>
                    <div className="h-2 rounded-full bg-white/[0.04] overflow-hidden">
                      <div
                        className={`h-full rounded-full transition-all ${levelColor[co.level]}`}
                        style={{ width: `${co.masteryPct}%` }}
                      />
                    </div>
                    <p className="mt-1 text-[10px] text-white/20">{co.correctAnswers}/{co.totalQuestions} correct</p>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Difficulty Breakdown */}
          {insights.difficultyBreakdown.length > 0 && (
            <div>
              <h3 className="mb-4 text-[10px] font-bold uppercase tracking-widest text-white/20">Difficulty Performance</h3>
              <div className="grid grid-cols-3 gap-4">
                {insights.difficultyBreakdown.map((d) => (
                  <div key={d.difficulty} className="rounded-xl border border-white/[0.04] bg-white/[0.01] p-4 text-center">
                    <p className={`text-[10px] font-bold uppercase tracking-widest mb-2 ${diffColor[d.difficulty]}`}>{d.difficulty}</p>
                    <p className="text-2xl font-black text-white/70">{d.pct}%</p>
                    <p className="text-[10px] text-white/20">{d.correct}/{d.total}</p>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Recommendations */}
          {insights.recommendations.length > 0 && (
            <div>
              <h3 className="mb-4 flex items-center gap-2 text-[10px] font-bold uppercase tracking-widest text-white/20">
                <AlertTriangle className="h-3 w-3 text-yellow-400" /> Study Recommendations
              </h3>
              <div className="space-y-2">
                {insights.recommendations.map((r, i) => (
                  <div key={i} className="flex items-center gap-3 rounded-lg border border-yellow-500/10 bg-yellow-500/[0.03] px-4 py-3">
                    <ChevronRight className="h-3 w-3 text-yellow-400 shrink-0" />
                    <p className="text-xs text-white/60">{r.message}</p>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      ) : (
        <div className="flex h-40 items-center justify-center rounded-xl border border-dashed border-white/[0.06]">
          <p className="text-xs font-bold text-white/20">Select a course to view insights</p>
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState, useRef, useCallback } from "react";
import { useParams } from "next/navigation";
import Link from "next/link";
import { ArrowLeft, Loader2, Clock, CheckCircle, AlertCircle, Shield } from "lucide-react";

interface QuizOption { id: string; text: string; orderIndex: number; }
interface QuizQuestion { id: string; text: string; marks: number; difficulty: string; orderIndex: number; options: QuizOption[]; }
interface QuizSession { id: string; startedAt: string; status: string; }
interface QuizInfo { title: string; durationMinutes: number; totalMarks: number; }

export default function QuizTakingPage() {
  const params = useParams<{ id: string }>();
  const [quizInfo, setQuizInfo] = useState<QuizInfo | null>(null);
  const [session, setSession] = useState<QuizSession | null>(null);
  const [questions, setQuestions] = useState<QuizQuestion[]>([]);
  const [answers, setAnswers] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [result, setResult] = useState<{ score: number; totalMarks: number; percentage: number } | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [timeLeft, setTimeLeft] = useState<number>(0); // seconds remaining
  const [tabSwitches, setTabSwitches] = useState(0);
  const timerRef = useRef<NodeJS.Timeout | null>(null);
  const autoSubmittedRef = useRef(false);

  // Track per-question start times
  const questionStartRef = useRef<Record<string, number>>({});
  const timeSpentRef = useRef<Record<string, number>>({});

  // POST proctor event
  const logProctorEvent = useCallback(async (eventType: string) => {
    if (!session) return;
    try {
      await fetch(`/api/student/quizzes/${params.id}/proctor`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ sessionId: session.id, eventType }),
      });
    } catch {}
  }, [session, params.id]);

  // Start quiz
  useEffect(() => {
    (async () => {
      const res = await fetch(`/api/student/quizzes/${params.id}/start`, { method: "POST" });
      if (!res.ok) {
        const err = await res.json();
        setError(err.error || "Failed to start quiz");
        setLoading(false);
        return;
      }
      const data = await res.json();
      setSession(data.session);
      setQuestions(data.questions);
      setQuizInfo(data.quiz);

      // Calculate time remaining using server time to nullify client clock skew
      const startTimeMs = new Date(data.session.startedAt).getTime();
      const serverTimeMs = new Date(data.serverTime).getTime();
      const endTimeMs = startTimeMs + data.quiz.durationMinutes * 60 * 1000;
      
      // Calculate how much time has ALREADY elapsed according to the server
      const elapsedMs = serverTimeMs - startTimeMs;
      const totalDurationMs = data.quiz.durationMinutes * 60 * 1000;
      
      const remaining = Math.max(0, Math.floor((totalDurationMs - elapsedMs) / 1000));
      setTimeLeft(remaining);

      // Initialize question start times
      if (data.questions.length > 0) {
        questionStartRef.current[data.questions[0].id] = Date.now();
      }

      setLoading(false);
    })();
  }, [params.id]);

  // Countdown timer
  useEffect(() => {
    if (loading || result) return;
    timerRef.current = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          clearInterval(timerRef.current!);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [loading, result]);

  // Auto-submit when timer hits 0
  useEffect(() => {
    if (timeLeft === 0 && !loading && !result && session && !autoSubmittedRef.current) {
      autoSubmittedRef.current = true;
      doSubmit(true);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [timeLeft, loading, result, session]);

  // Tab-switch / visibility tracking
  useEffect(() => {
    if (!session || result) return;

    const handleVisibility = () => {
      if (document.hidden) {
        logProctorEvent("tab_switch");
        setTabSwitches((prev) => prev + 1);
      } else {
        logProctorEvent("focus");
      }
    };

    const handleCopy = (e: ClipboardEvent) => {
      e.preventDefault();
      logProctorEvent("copy_attempt");
    };

    const handleContextMenu = (e: MouseEvent) => {
      e.preventDefault();
    };

    document.addEventListener("visibilitychange", handleVisibility);
    document.addEventListener("copy", handleCopy);
    document.addEventListener("contextmenu", handleContextMenu);

    return () => {
      document.removeEventListener("visibilitychange", handleVisibility);
      document.removeEventListener("copy", handleCopy);
      document.removeEventListener("contextmenu", handleContextMenu);
    };
  }, [session, result, logProctorEvent]);

  const doSubmit = async (auto = false) => {
    if (!session || submitting) return;
    if (!auto && !confirm("Are you sure you want to submit? You cannot change answers after submission.")) return;

    setSubmitting(true);
    try {
      const answerArray = Object.entries(answers).map(([questionId, selectedOptionId]) => {
        const timeTaken = timeSpentRef.current[questionId];
        return {
          questionId,
          selectedOptionId,
          timeTakenSeconds: timeTaken ? Math.round(timeTaken / 1000) : undefined,
        };
      });

      const res = await fetch(`/api/student/quizzes/${params.id}/submit`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ sessionId: session.id, answers: answerArray }),
      });

      if (!res.ok) {
        const err = await res.json();
        alert(err.error || "Submission failed");
        return;
      }

      const data = await res.json();
      setResult(data);
    } finally {
      setSubmitting(false);
    }
  };

  const selectAnswer = (questionId: string, optionId: string) => {
    // Track time spent
    if (questionStartRef.current[questionId]) {
      const elapsed = Date.now() - questionStartRef.current[questionId];
      timeSpentRef.current[questionId] = (timeSpentRef.current[questionId] || 0) + elapsed;
    }
    questionStartRef.current[questionId] = Date.now();
    setAnswers({ ...answers, [questionId]: optionId });
  };

  const formatTime = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m.toString().padStart(2, "0")}:${s.toString().padStart(2, "0")}`;
  };

  if (loading) {
    return (
      <div className="flex h-60 items-center justify-center">
        <Loader2 className="h-5 w-5 animate-spin text-white/20" />
      </div>
    );
  }

  if (error) {
    return (
      <div>
        <Link href="/dashboard/student/quizzes" className="mb-6 inline-flex items-center gap-2 text-[10px] font-bold uppercase tracking-widest text-white/30 hover:text-white transition-colors">
          <ArrowLeft className="h-3 w-3" /> Back
        </Link>
        <div className="flex h-40 items-center justify-center rounded-xl border border-dashed border-red-500/20">
          <p className="text-xs font-bold uppercase tracking-widest text-red-400 flex items-center gap-2">
            <AlertCircle className="h-4 w-4" /> {error}
          </p>
        </div>
      </div>
    );
  }

  // Result screen
  if (result) {
    const pct = result.percentage;
    const color = pct >= 70 ? "text-emerald-400" : pct >= 40 ? "text-yellow-400" : "text-red-400";
    return (
      <div className="flex flex-col items-center justify-center min-h-[50vh]">
        <div className="rounded-xl border border-white/[0.06] bg-white/[0.01] p-12 text-center max-w-md">
          <CheckCircle className={`h-12 w-12 mx-auto mb-6 ${color}`} />
          <h2 className="text-2xl font-black uppercase tracking-tight text-white mb-2">Quiz Submitted!</h2>
          <p className="text-xs font-bold uppercase tracking-widest text-white/30 mb-8">{quizInfo?.title}</p>
          <div className="grid grid-cols-3 gap-4 mb-8">
            <div>
              <p className="text-[9px] font-bold text-white/20 uppercase tracking-widest mb-1">Score</p>
